import { renderWorkMode } from './work-mode.js';
import { WorkflowStudio, workflowNames } from './workflow-studio.js';
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const pretty = value => esc(JSON.stringify(value, null, 2));
const key = () => crypto.randomUUID();
const statusText = { pending: 'Chưa chạy', queued: 'Đang chờ', running: 'Đang thực hiện', produced: 'Đã tạo output', passed: 'Đạt kiểm tra', approved: 'Owner đã duyệt', completed: 'Hoàn tất', blocked: 'Bị chặn', failed: 'Thất bại', interrupted: 'Gián đoạn', waiting_input: 'Chờ input', waiting_approval: 'Chờ Owner', awaiting_plan_approval: 'Chờ duyệt kế hoạch', awaiting_final_approval: 'Chờ duyệt kết quả', awaiting_release: 'Chờ thao tác Git', cancelled: 'Đã hủy', paused: 'Tạm dừng', not_run: 'Chưa thực thi', skipped_satisfied: 'Bỏ qua theo policy', superseded: 'Đã thay thế' };
