    $('companyLiveCursor').textContent = 'Đang đồng bộ';
    const visibleAgents = (this.state.office?.agents ?? []).filter(a => !this.departmentFilter || this.data.agentConfigurations.find(c => c.agentId === a.agent.agentId)?.department === this.departmentFilter);
