    if (run.state === 'awaiting_plan_approval') action('software-preview-scope', 'Xem scope & duyệt kế hoạch', async () => {
      const preview = await this.mutate(path + '/execution-preview', { expectedSequence: run.lastSequence });
      this.s.dialog('Duyệt phạm vi thực hiện', `<p>${esc(preview.seed.project.name)} · ${preview.plan.tasks.length} công việc</p><dl class="review-facts"><dt>Repository</dt><dd>${esc(preview.seed.project.repositoryPath)}</dd><dt>Phạm vi ghi</dt><dd>${esc(preview.seed.project.writePaths.join(', '))}</dd><dt>Build</dt><dd>${esc([preview.seed.project.build.executable, ...preview.seed.project.build.arguments].join(' '))}</dd><dt>Test</dt><dd>${esc([preview.seed.project.test.executable, ...preview.seed.project.test.arguments].join(' '))}</dd></dl><ul>${preview.plan.tasks.map(task => `<li>${esc(task.title)} · ${esc(this.agentName(task.agentId))}</li>`).join('')}</ul>${technicalDetails({ repository: preview.seed.project.repositoryPath, baseCommit: preview.seed.repository.baseCommit, plan: preview.plan, grant: preview.grant, build: preview.seed.project.build, test: preview.seed.project.test }, 'Toàn bộ phạm vi & mã kiểm chứng')}<p class="helper">Giới hạn: 1 GiB RAM, 2 CPU, 128 process/container, timeout theo command. Không cấp quyền sửa working directory gốc, push, merge hoặc deploy.</p><button class="button primary" id="approveSoftwareScope">Duyệt scope này</button>`);
      this.bind('approveSoftwareScope', async () => { await this.mutate(path + '/plan-approval', { expectedSequence: preview.lastSequence, approved: true, manifestSha256: preview.grant.manifestSha256 }); $('detailDialog').close(); });
    }, true);
