      const stage = run.state === 'awaiting_plan_approval' ? 'plan' : 'delivery';
      this.s.dialog('Owner yêu cầu sửa', `<form id="softwareRevisionForm"><label for="softwareRevisionFeedback">Phản hồi cho ${stage === 'plan' ? 'Leader' : 'Dev'}</label><textarea id="softwareRevisionFeedback" required maxlength="2000"></textarea><p class="helper">Phản hồi được lưu vào ngữ cảnh mới. Sửa sản phẩm giữ nguyên phạm vi đã duyệt và tạo candidate/receipts mới.</p><button class="button primary" type="submit">Gửi yêu cầu sửa</button></form>`);
      this.form('softwareRevisionForm', () => this.mutate(path + '/revision', { expectedSequence: run.lastSequence, stage, feedback: $('softwareRevisionFeedback').value }));
