    const safeState = id => ['passed', 'produced', 'approved', 'running', 'failed', 'blocked', 'waiting_approval'].includes(nodeState(id)) ? nodeState(id) : 'pending';
    const edges = nodes.flatMap(n => n.dependsOn.map(dep => { const from = positions[dep], to = positions[n.id]; if (!from || !to) return ''; const [x, y] = from, [tx, ty] = to; return `<path d="M${x + 65},${y + 56} C${x + 65},${y + 85} ${tx + 65},${ty - 25} ${tx + 65},${ty}" class="workflow-edge" marker-end="url(#workflowArrow)"/>`; })).join('');
    $('softwareGraph').innerHTML = `<svg viewBox="0 0 860 430" role="group" aria-label="Software delivery workflow DAG"><defs><marker id="workflowArrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" class="workflow-arrow"/></marker></defs>${edges}${nodes.map(n => { const [x, y] = positions[n.id] ?? [700, 130]; return `<g transform="translate(${x} ${y})" tabindex="0" role="button" aria-label="${esc(nodeLabels[n.id] ?? n.id)}: ${esc(statusText[nodeState(n.id)] ?? nodeState(n.id))}" class="workflow-node ${safeState(n.id)} ${this.nodeId === n.id ? 'selected' : ''}" data-workflow-node="${esc(n.id)}"><rect width="132" height="56" rx="7"/><text x="10" y="22">${esc(nodeLabels[n.id] ?? n.id)}</text><text x="10" y="42" class="node-state-label">${esc(statusText[nodeState(n.id)] ?? nodeState(n.id))}</text></g>`; }).join('')}</svg>`;
    document.querySelectorAll('[data-workflow-node]').forEach(n => { const select = () => { this.nodeId = n.dataset.workflowNode; this.renderNode(run); }; n.onclick = select; n.onkeydown = e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(); } }; });
    $('softwareTasks').innerHTML = (run.plan?.tasks ?? []).map(t => { const job = run.jobs.filter(j => j.taskId === t.id && j.round === run.round).at(-1); return `<article class="task-card"><span class="tag">${esc(statusText[job?.status] ?? 'Chờ công việc trước')}</span><h3>${esc(t.title)}</h3><p class="meta">${esc(this.agentName(t.agentId))} · ${esc(t.allowedPaths.join(', '))}</p><p class="helper">${t.acceptanceIds.length} tiêu chí nghiệm thu · ${t.dependsOn.length ? `${t.dependsOn.length} công việc cần hoàn thành trước` : 'Có thể bắt đầu độc lập'}</p><button class="button" data-task-node="dev-${esc(t.id)}">Mở task / output</button>${technicalDetails({ taskId: t.id, acceptanceIds: t.acceptanceIds, dependsOn: t.dependsOn })}</article>`; }).join('') || '<p class="helper">Leader chưa xuất TaskGraph.</p>';
