    document.querySelectorAll('[data-cloud-preview]').forEach(b => b.onclick = () => this.cloudPreviewForm(b.dataset.cloudPreview, b.dataset.cloudAgent));
    $('companyConsultations').innerHTML = this.data.consultations.filter(j => j.runId === scope && j.branchId === this.branchScope && !j.comparisonId).slice(-6).map(j => `<div class="consultation-status"><b>${esc(j.binding.agent.name)}</b><span class="tag">${esc(statusText[j.status] ?? j.status)}</span><p class="meta">${esc(j.binding.model?.name ?? 'Model đã cấu hình')} · Lần ${j.attempts}/2</p>${j.error ? '<p class="helper">Lần gọi chưa hoàn tất. Xem chi tiết để xử lý hoặc thử lại.</p>' : ''}${['failed', 'interrupted'].includes(j.status) && j.attempts < 2 ? `<button class="button" data-consult-retry="${esc(j.jobId)}">Thử lại</button>` : ''}${technicalDetails({ jobId: j.jobId, contextSnapshotSha256: j.contextSnapshotSha256, error: j.error, usage: j.usage }, 'Ngữ cảnh & bằng chứng')}</div>`).join('');
    $('companyConsultations').insertAdjacentHTML('beforeend', this.comparisonResults(scope));
    document.querySelectorAll('[data-consult-retry]').forEach(b => b.onclick = async () => { try { await this.mutate(`/consultations/${b.dataset.consultRetry}/retry`, {}); } catch (e) { this.s.toast(e.message); } });
    const egress = this.data.egressManifests.filter(m => m.runId === scope && m.branchId === this.branchScope).slice(0, 12);
