    document.querySelectorAll('[data-egress-view]').forEach(b => b.onclick = () => this.showEgressManifest(this.data.egressManifests.find(m => m.manifestId === b.dataset.egressView)));
    document.querySelectorAll('[data-egress-retry]').forEach(b => b.onclick = async () => { try { await this.mutate(`/cloud/egress/${b.dataset.egressRetry}/retry`, {}); } catch (e) { this.s.toast(e.message); } });
    $('companyMeetings').innerHTML = this.data.meetings.filter(m => m.runId === scope).map(m => `<article class="record"><span class="tag">${esc(({ scheduled: 'Đã lên lịch', started: 'Đang họp', completed: 'Đã lưu biên bản' })[m.state] ?? m.state)}</span><h3>${esc(m.agenda)}</h3><p class="meta">${esc(m.participants.map(id => this.agentName(id)).join(' · '))}</p>${m.summary ? `<p>${esc(m.summary)}</p><ul>${m.actionItems.map(i => `<li>${esc(i)}</li>`).join('')}</ul><p class="helper">Biên bản được lưu làm nguồn. Quyết định cần bạn duyệt trong Kiến thức.</p>` : ''}${m.state === 'scheduled' ? `<button class="button primary" data-start-meeting="${esc(m.meetingId)}">Bắt đầu họp</button>` : m.state === 'started' ? `<button class="button" data-complete-meeting="${esc(m.meetingId)}">Ghi biên bản</button><button class="button" data-summarize-meeting="${esc(m.meetingId)}">Leader tóm tắt bằng AI local</button>` : ''}</article>`).join('') || '<div class="collaboration-empty"><h3>Cuộc họp của đội ngũ</h3><p>Mời các nhân viên trao đổi về một mục tiêu, sau đó lưu biên bản và việc cần làm.</p><button class="button" id="emptyScheduleMeeting">Mời họp</button></div>';
    this.bind('emptyScheduleMeeting', () => this.meetingForm());
    document.querySelectorAll('[data-start-meeting]').forEach(b => b.onclick = async () => { try { const m = this.data.meetings.find(m => m.meetingId === b.dataset.startMeeting); await this.mutate(`/meetings/${m.meetingId}/start`, { expectedVersion: m.version, summary: '', actionItems: [], citations: [] }); } catch (e) { this.s.toast(e.message); } });
    document.querySelectorAll('[data-complete-meeting]').forEach(b => b.onclick = () => { const m = this.data.meetings.find(m => m.meetingId === b.dataset.completeMeeting); this.s.dialog('Biên bản Owner ghi nhận', `<form id="meetingMinutesForm"><label for="meetingSummary">Tóm tắt công khai</label><textarea id="meetingSummary" required maxlength="4000"></textarea><label for="meetingActions">Action items, mỗi dòng một mục</label><textarea id="meetingActions" maxlength="12000"></textarea><button class="button primary" type="submit">Lưu biên bản</button></form>`); this.form('meetingMinutesForm', () => this.mutate(`/meetings/${m.meetingId}/complete`, { expectedVersion: m.version, summary: $('meetingSummary').value, actionItems: $('meetingActions').value.split('\n').filter(Boolean), citations: [] })); });
    document.querySelectorAll('[data-summarize-meeting]').forEach(b => b.onclick = async () => { try { const m = this.data.meetings.find(m => m.meetingId === b.dataset.summarizeMeeting); const a = this.state.agents.find(a => m.participants.includes(a.agentId) && a.roleIds.includes('leader')); if (!a) throw new Error('Cuộc họp cần một participant có role Leader để tóm tắt.'); await this.mutate(`/meetings/${m.meetingId}/summarize`, { agentId: a.agentId, roleId: 'leader' }); } catch (e) { this.s.toast(e.message); } });
